function kc_seed($actor='root')
{
 $name=in_array($actor,array('config','article','category','type'),true)?'junior':($actor==='group'?'moderator':$actor);
 kp_reset($name);kp_sql('DELETE FROM fixture_kb_config');
 $seed=file_get_contents($GLOBALS['kp_source'].'install/schemas/mysql_basic.sql');
 preg_match_all('/^INSERT INTO phpbb_kb_config\b[^\r\n]*;/m',$seed,$matches);kp_check(count($matches[0])===26,'All actual canonical KB config defaults');
 foreach($matches[0]as$sql){kp_sql(str_replace('phpbb_kb_config','fixture_kb_config',$sql));}
 kp_sql("INSERT INTO fixture_kb_config VALUES('custom_keep','Keep unknown setting')");
 if(in_array($actor,array('config','article','category','type'),true)){
  $routes=array('config'=>array('Configuration','admin_kb_config.php?mode=config'),'article'=>array('Art_man','admin_kb_art.php'),
   'category'=>array('Cat_man','admin_kb_cat.php'),'type'=>array('Types_man','admin_kb_types.php'));
  kp_sql("UPDATE fixture_jr_admin_users SET user_jr_admin='".md5('KB_title'.$routes[$actor][0].$routes[$actor][1])."' WHERE user_id=2");
 }
}
